import { useState, useEffect } from 'react';
const API = 'http://localhost:5000/api';
const getToken = () => localStorage.getItem('examai_token');

const TYPE_CONFIG = {
  info:   { color:'#2563eb', bg:'#dbeafe', border:'#bfdbfe', icon:'ℹ', label:'Info' },
  success:{ color:'#16a34a', bg:'#dcfce7', border:'#bbf7d0', icon:'✓', label:'Success' },
  warning:{ color:'#d97706', bg:'#fef3c7', border:'#fde68a', icon:'⚠', label:'Warning' },
  urgent: { color:'#dc2626', bg:'#fee2e2', border:'#fecaca', icon:'🚨', label:'Urgent' },
};

export default function Notifications({ store }) {
  const [notifs,  setNotifs]  = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving,  setSaving]  = useState(false);
  const [deleting,setDeleting]= useState({});
  const [form,    setForm]    = useState({
    title:'', message:'', type:'info',
    expires_at: '', // optional expiry date
  });
  const isAdmin = store.currentUser.role === 'admin';

  const apiFetch = async (path, opts={}) => {
    const res = await fetch(`${API}${path}`, {
      headers:{ Authorization:`Bearer ${getToken()}`, 'Content-Type':'application/json' },
      ...opts
    });
    return res.json();
  };

  useEffect(() => { load(); }, []);

  // Auto-remove expired notifications from display
  useEffect(() => {
    const t = setInterval(() => {
      const now = new Date();
      setNotifs(prev => prev.filter(n => {
        if (!n.expires_at) return true;
        return new Date(n.expires_at) > now;
      }));
    }, 60000); // check every minute
    return () => clearInterval(t);
  }, []);

  const load = async () => {
    setLoading(true);
    const d = await apiFetch('/notifications');
    const now = new Date();
    // Filter out expired ones on load too
    const active = Array.isArray(d) ? d.filter(n => !n.expires_at || new Date(n.expires_at) > now) : [];
    setNotifs(active);
    setLoading(false);
  };

  const handlePost = async () => {
    if (!form.title || !form.message) { store.addToast('Title and message required','error'); return; }
    setSaving(true);
    const payload = { title:form.title, message:form.message, type:form.type };
    if (form.expires_at) payload.expires_at = new Date(form.expires_at).toISOString();
    const d = await apiFetch('/notifications', { method:'POST', body:JSON.stringify(payload) });
    if (d.error) store.addToast(d.error,'error');
    else {
      setNotifs(n => [d, ...n]);
      setForm({ title:'', message:'', type:'info', expires_at:'' });
      store.addToast('📢 Announcement posted!','success');
    }
    setSaving(false);
  };

  const handleDelete = async (id) => {
    setDeleting(d => ({...d, [id]:true}));
    await apiFetch(`/notifications/${id}`, { method:'DELETE' });
    setNotifs(n => n.filter(x => x.notif_id !== id));
    store.addToast('Notification removed','info');
    setDeleting(d => ({...d, [id]:false}));
  };

  const isExpired = (n) => n.expires_at && new Date(n.expires_at) <= new Date();
  const timeLeft  = (n) => {
    if (!n.expires_at) return null;
    const diff = new Date(n.expires_at) - new Date();
    if (diff <= 0) return 'Expired';
    const h = Math.floor(diff / 3600000);
    const m = Math.floor((diff % 3600000) / 60000);
    if (h > 24) return `Expires in ${Math.floor(h/24)}d`;
    if (h > 0)  return `Expires in ${h}h ${m}m`;
    return `Expires in ${m}m`;
  };

  return (
    <div className="fade-up">
      {/* Header — matches Image 6 */}
      <div style={{ display:'flex', alignItems:'center', gap:12, marginBottom:6 }}>
        <span style={{ fontSize:28 }}>📢</span>
        <h1 style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:28, color:'#0f0f1a' }}>
          {isAdmin ? 'Announcements' : 'Notifications'}
        </h1>
      </div>
      <p style={{ fontSize:13, color:'#6b7280', marginBottom:24, fontFamily:'JetBrains Mono,monospace' }}>
        {isAdmin ? 'Post updates visible to all students.' : 'View updates from your department.'}
      </p>

      {/* Post form — admin only, matches Image 6 */}
      {isAdmin && (
        <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, padding:24, marginBottom:20, boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
          <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:16, color:'#0f0f1a', marginBottom:20 }}>Post Announcement</div>

          {/* Title */}
          <div style={{ marginBottom:14 }}>
            <label style={{ display:'block', fontSize:11, fontWeight:700, color:'#7c3aed', marginBottom:6, textTransform:'uppercase', letterSpacing:1.5, fontFamily:'JetBrains Mono,monospace' }}>TITLE</label>
            <input className="form-input" value={form.title}
              onChange={e=>setForm(f=>({...f,title:e.target.value}))}
              placeholder="e.g. Exam Schedule Update"
              style={{ fontFamily:'JetBrains Mono,monospace', fontSize:13 }}/>
          </div>

          {/* Message */}
          <div style={{ marginBottom:14 }}>
            <label style={{ display:'block', fontSize:11, fontWeight:700, color:'#7c3aed', marginBottom:6, textTransform:'uppercase', letterSpacing:1.5, fontFamily:'JetBrains Mono,monospace' }}>MESSAGE</label>
            <textarea className="form-textarea" value={form.message}
              onChange={e=>setForm(f=>({...f,message:e.target.value}))}
              placeholder="Write your announcement..."
              style={{ minHeight:100, fontFamily:'JetBrains Mono,monospace', fontSize:13, resize:'vertical' }}/>
          </div>

          {/* Type + Expiry row */}
          <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:14, marginBottom:16 }}>
            <div>
              <label style={{ display:'block', fontSize:11, fontWeight:700, color:'#7c3aed', marginBottom:6, textTransform:'uppercase', letterSpacing:1.5, fontFamily:'JetBrains Mono,monospace' }}>TYPE</label>
              <div style={{ position:'relative' }}>
                <span style={{ position:'absolute', left:12, top:'50%', transform:'translateY(-50%)', fontSize:13 }}>
                  {TYPE_CONFIG[form.type]?.icon}
                </span>
                <select className="form-select" value={form.type}
                  onChange={e=>setForm(f=>({...f,type:e.target.value}))}
                  style={{ paddingLeft:32, fontFamily:'JetBrains Mono,monospace' }}>
                  <option value="info">ℹ Info</option>
                  <option value="success">✓ Success</option>
                  <option value="warning">⚠ Warning</option>
                  <option value="urgent">🚨 Urgent</option>
                </select>
              </div>
            </div>
            <div>
              <label style={{ display:'block', fontSize:11, fontWeight:700, color:'#7c3aed', marginBottom:6, textTransform:'uppercase', letterSpacing:1.5, fontFamily:'JetBrains Mono,monospace' }}>
                AUTO-EXPIRE (optional)
              </label>
              <input type="datetime-local" className="form-input" value={form.expires_at}
                onChange={e=>setForm(f=>({...f,expires_at:e.target.value}))}
                style={{ fontFamily:'JetBrains Mono,monospace', fontSize:12 }}/>
              <div style={{ fontSize:10, color:'#9ca3af', marginTop:4, fontFamily:'JetBrains Mono,monospace' }}>
                Set expiry to auto-remove on that date/time
              </div>
            </div>
          </div>

          {/* Post button — right-aligned like Image 6 */}
          <div style={{ display:'flex', justifyContent:'flex-end' }}>
            <button onClick={handlePost} disabled={saving}
              style={{ padding:'10px 24px', background:'#5b21b6', color:'#fff', borderRadius:10, border:'none', fontWeight:700, fontSize:13, cursor:'pointer', display:'flex', alignItems:'center', gap:8, fontFamily:'JetBrains Mono,monospace', opacity:saving?.7:1 }}>
              {saving ? <><div className="spinner" style={{width:12,height:12,borderColor:'rgba(255,255,255,.3)',borderTopColor:'white'}}/>Posting...</> : <><span>📢</span> Post</>}
            </button>
          </div>
        </div>
      )}

      {/* Notifications list */}
      <div style={{ background:'#fff', border:'1px solid #e8e8f0', borderRadius:14, overflow:'hidden', boxShadow:'0 1px 3px rgba(0,0,0,.05)' }}>
        {loading ? (
          <div style={{ display:'flex', alignItems:'center', gap:12, padding:40, justifyContent:'center' }}>
            <div className="spinner" style={{width:24,height:24}}/><span style={{color:'#6b7280'}}>Loading...</span>
          </div>
        ) : notifs.length === 0 ? (
          <div style={{ textAlign:'center', padding:'48px 24px' }}>
            <div style={{ fontSize:48, marginBottom:12, opacity:.35 }}>🔔</div>
            <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:15, color:'#374151', marginBottom:6 }}>No announcements yet</div>
            <div style={{ fontSize:13, color:'#9ca3af' }}>{isAdmin ? 'Post your first announcement above.' : 'Check back later for updates.'}</div>
          </div>
        ) : notifs.map((n, i) => {
          const cfg = TYPE_CONFIG[n.type] || TYPE_CONFIG.info;
          const expired = isExpired(n);
          const tl = timeLeft(n);
          return (
            <div key={n.notif_id} style={{ display:'flex', alignItems:'flex-start', gap:14, padding:'16px 20px', borderBottom: i < notifs.length-1 ? '1px solid #f3f4f6' : 'none', background: expired ? '#fafafa' : '#fff', opacity: expired ? 0.6 : 1, transition:'background .2s' }}
              onMouseEnter={e=>{ if(!expired) e.currentTarget.style.background='#f8f8fc'; }}
              onMouseLeave={e=>e.currentTarget.style.background=expired?'#fafafa':'#fff'}>
              {/* Icon */}
              <div style={{ width:38, height:38, borderRadius:10, background:cfg.bg, border:`1px solid ${cfg.border}`, display:'flex', alignItems:'center', justifyContent:'center', fontSize:16, flexShrink:0 }}>
                {cfg.icon}
              </div>
              {/* Content */}
              <div style={{ flex:1, minWidth:0 }}>
                <div style={{ display:'flex', alignItems:'center', gap:8, marginBottom:4, flexWrap:'wrap' }}>
                  <span style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:700, fontSize:14, color: expired ? '#9ca3af' : cfg.color }}>{n.title}</span>
                  <span style={{ padding:'1px 8px', borderRadius:20, background:cfg.bg, color:cfg.color, fontSize:9, fontWeight:700, fontFamily:'JetBrains Mono,monospace', border:`1px solid ${cfg.border}` }}>{cfg.label}</span>
                  {expired && <span style={{ padding:'1px 8px', borderRadius:20, background:'#f3f4f6', color:'#9ca3af', fontSize:9, fontWeight:700, fontFamily:'JetBrains Mono,monospace' }}>EXPIRED</span>}
                </div>
                <div style={{ fontSize:13, color: expired ? '#9ca3af' : '#374151', lineHeight:1.6, marginBottom:6 }}>{n.message}</div>
                <div style={{ display:'flex', gap:12, flexWrap:'wrap', fontSize:10, color:'#9ca3af', fontFamily:'JetBrains Mono,monospace', alignItems:'center' }}>
                  <span>By {n.admin_name || 'Admin'}</span>
                  <span>·</span>
                  <span>{new Date(n.created_at).toLocaleString('en-US',{month:'short',day:'numeric',year:'numeric',hour:'2-digit',minute:'2-digit'})}</span>
                  {tl && !expired && (
                    <><span>·</span><span style={{ color:'#d97706', fontWeight:600 }}>⏰ {tl}</span></>
                  )}
                  {expired && n.expires_at && (
                    <><span>·</span><span style={{ color:'#dc2626' }}>Expired {new Date(n.expires_at).toLocaleDateString()}</span></>
                  )}
                </div>
              </div>
              {/* Delete button — admin only */}
              {isAdmin && (
                <button onClick={() => handleDelete(n.notif_id)} disabled={deleting[n.notif_id]}
                  style={{ width:32, height:32, borderRadius:8, background:'#fee2e2', border:'1px solid #fecaca', color:'#dc2626', cursor:'pointer', display:'flex', alignItems:'center', justifyContent:'center', fontSize:14, flexShrink:0, transition:'all .15s' }}
                  title="Remove notification"
                  onMouseEnter={e=>{e.currentTarget.style.background='#fecaca';}}
                  onMouseLeave={e=>{e.currentTarget.style.background='#fee2e2';}}>
                  {deleting[n.notif_id] ? <div className="spinner" style={{width:10,height:10,borderColor:'#fecaca',borderTopColor:'#dc2626'}}/> : '🗑'}
                </button>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}
